{
  "Topic": "Here are five things you missed while creating your healthcare resume",
  "Description": "Description goes here"
}

parameters.jsCode:
// Input: items[0].json = your original array

const input = items[0].json;
const dataArray = Array.isArray(input) ? input : [input];

const results = dataArray.map(entry => {
  const data = entry["Existing Topics (and descriptions)"];

  if (!data) {
    return {
      json: {
        Topic: [],
        Description: [],
        ExistingTopics: [],
        recipient: "aryaniyappan2006@gmail.com"
      }
    };
  }

  const topicMatch = data.match(/Topic:\s*\[(.*?)\],/s);
  const descMatch = data.match(/Description:\s*\[(.*?)\]\s*}/s);

  const topics = topicMatch ? topicMatch[1].split(",").map(t => t.trim()) : [];
  const descriptions = descMatch ? descMatch[1].split(",").map(d => d.trim()) : [];

  // Pair topics and descriptions
  const existingTopics = topics.map((t, i) => ({
    topic: t,
    description: descriptions[i] || null
  }));

  return {
    json: {
      ExistingTopics:  JSON.stringify(existingTopics),
      recipient: "aryaniyappan2006@gmail.com"
    }
  };
});

return results;
